// InterfaceKey is Interface's row identity (ancestor keys in canonical form).
type InterfaceKey struct {
	Name string
}

// InterfaceDescriptor is the list descriptor callers hand to a protocol library.
func InterfaceDescriptor() yang.ListDescriptor[Interface, InterfaceKey] {
	return yang.ListDescriptor[Interface, InterfaceKey]{
		Codec: yang.StructRowCodec(InterfaceSchema, func(r *Interface) InterfaceKey {
			var k InterfaceKey
			if r.Name != nil {
				k.Name = *r.Name
			}
			return k
		}),
		Path: yang.JoinPath(yang.In(moduleOpenconfigMacsec, "macsec", "interfaces", "interface")),
	}
}

